  const panel={ position:'fixed', zIndex:8888, top:0, width:'50%', height:'100vh', background:ACCENT, transitionProperty:'transform', transitionDuration:'460ms', transitionTimingFunction:'cubic-bezier(0.76,0,0.24,1)', pointerEvents:phase!=='idle'?'all':'none' };
